fn frame(t: i32) {
    host::display::clear(0x0d0d12);
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, -1);
        host::display::state_set(4, 30);
    }
    let mut h: i32 = host::display::state_get(1);
    let mut s: i32 = -1;
    if h >= 0 {
        s = host::net::status(h);
    }
    if h < 0 || s == 3 {
        if s == 3 {
            host::net::close(h);
            host::display::state_set(1, -1);
            h = -1;
        }
        let wait: i32 = host::display::state_get(3);
        if wait > 0 {
            host::display::state_set(3, wait - 1);
        } else {
            host::display::state_set(2, host::display::state_get(2) + 1);
            host::display::state_set(1, host::net::open("wss://relay.example.net/feed"));
            let mut back: i32 = host::display::state_get(4) * 2;
            if back > 480 {
                back = 480;
            }
            host::display::state_set(4, back);
            host::display::state_set(3, back);
        }
    }
    host::display::draw_string(120, 50, "RECONNECTOR", 0xffffff, 2);
    host::display::draw_string(80, 140, "ATTEMPTS", 0x888888, 1);
    host::display::draw_number(80, 160, host::display::state_get(2), 0xffffff, 3);
    host::display::draw_string(80, 230, "BACKOFF FRAMES", 0x888888, 1);
    host::display::draw_number(80, 250, host::display::state_get(4), 0xaa7700, 3);
    host::display::draw_string(80, 320, "RETRY IN", 0x888888, 1);
    let wait2: i32 = host::display::state_get(3);
    host::display::draw_number(80, 340, wait2, 0x66ddff, 3);
    if h >= 0 && s == 1 {
        host::display::draw_string(80, 420, "CONNECTED", 0x22bb44, 2);
    } else if h >= 0 && s == 0 {
        host::display::draw_string(80, 420, "DIALING", 0xaa7700, 2);
    } else {
        host::display::draw_string(80, 420, "DOWN", 0xbb3333, 2);
    }
    host::display::present();
}
